              end
              3'b101: begin  // PC
                pc_load = 1'b1;
                pc_val  = v[4:0];
              end
              3'b110: begin  // ISR
                isr_n     = v;
                isr_cnt_n = nbits;
              end
              default: begin  // EXEC
                is_exec      = 1'b1;
                latch_n      = v[15:0];
                latch_pend_n = 1'b1;
                latch_host_n = 1'b0;
              end
            endcase
            // refill after the shift
            if (cfg_autopull && osr_cnt_n >= pull_th && !tx_empty) begin
              tx_pop    = 1'b1;
              osr_n     = tx_head;
              osr_cnt_n = 6'd0;
            end
          end
        end

        // ---- PUSH / PULL ----
        3'b100: begin
          if (!instr[7]) begin
            // PUSH
            if (instr[6] && isr_cnt < push_th) begin
              // IfFull and below threshold: no-op
            end else if (rx_full) begin
              rxstall_set = 1'b1;
              if (instr[5]) stall = 1'b1;
              else begin
                isr_n     = 32'd0;
                isr_cnt_n = 6'd0;
              end
            end else begin
              rx_push      = 1'b1;
              rx_push_data = isr;
              isr_n        = 32'd0;
              isr_cnt_n    = 6'd0;
            end
          end else begin
            // PULL
            if (cfg_autopull && osr_cnt == 6'd0) begin
              // OSR full: barrier no-op
            end else if (instr[6] && osr_cnt < pull_th) begin
              // IfEmpty and below threshold: no-op
            end else if (tx_empty) begin
              if (instr[5]) begin
                stall       = 1'b1;
                txstall_set = 1'b1;
              end else begin
                osr_n     = x;
                osr_cnt_n = 6'd0;
              end
            end else begin
              tx_pop    = 1'b1;
              osr_n     = tx_head;
              osr_cnt_n = 6'd0;
            end
          end
        end

        // ---- MOV ----
        3'b101: begin
          // reserved: destination 011, op 11, source 100 -> NOP
          if (f75 != 3'b011 && instr[4:3] != 2'b11 && instr[2:0] != 3'b100) begin
            stat_level = cfg_status_sel ? rx_level : tx_level;
            unique case (instr[2:0])
              3'b000:  src_v = in_rot;
              3'b001:  src_v = x;
              3'b010:  src_v = y;
              3'b101:  src_v = (SW'(stat_level) < SW'(cfg_status_n)) ? 32'hFFFF_FFFF : 32'd0;
              3'b110:  src_v = isr;
              3'b111:  src_v = osr;
              default: src_v = 32'd0;  // NULL
            endcase
            unique case (instr[4:3])
              2'b01:   v = ~src_v;
              2'b10:   v = bitrev(src_v);
              default: v = src_v;
            endcase
            unique case (f75)
              3'b000: begin  // PINS
                os_we    = 1'b1;
                os_dir   = 1'b0;
                os_base  = cfg_out_base;
                os_count = {1'b0, cfg_out_count};
                os_val   = v;
              end
              3'b001: x_n = v;
              3'b010: y_n = v;
              3'b100: begin  // EXEC
                is_exec      = 1'b1;
                latch_n      = v[15:0];
                latch_pend_n = 1'b1;
                latch_host_n = 1'b0;
              end
              3'b101: begin  // PC
                pc_load = 1'b1;
                pc_val  = v[4:0];
              end
              3'b110: begin  // ISR
                isr_n     = v;
                isr_cnt_n = 6'd0;
              end
              default: begin  // OSR
                osr_n     = v;
                osr_cnt_n = 6'd0;
              end
            endcase
          end
        end

        // ---- IRQ: NOP carrying side-set and delay ----
        3'b110: ;

        // ---- SET ----
        default: begin
          unique case (f75)
            3'b000: begin  // PINS
              os_we    = 1'b1;
              os_dir   = 1'b0;
              os_base  = cfg_set_base;
              os_count = {4'd0, cfg_set_count};
              os_val   = {27'd0, f40};
            end
            3'b001: x_n = {27'd0, f40};
            3'b010: y_n = {27'd0, f40};
            3'b100: begin  // PINDIRS
              os_we    = 1'b1;
              os_dir   = 1'b1;
              os_base  = cfg_set_base;
              os_count = {4'd0, cfg_set_count};
              os_val   = {27'd0, f40};
            end
            default: ;  // reserved: NOP
          endcase
        end
      endcase

      // 3. bookkeeping
      if (stall) begin
        // a stalled instruction has no main effect: drop its OUT/SET pin write
        os_we     = 1'b0;
        stalled_n = 1'b1;
        if (!src_imem) begin
          latch_n      = instr;
          latch_pend_n = 1'b1;
          latch_host_n = src_host || latch_host;
        end
      end else begin
        stalled_n = 1'b0;
        if (!src_imem && !is_exec) latch_pend_n = 1'b0;
        // pc_update(I, src)
        if (pc_load) pc_n = PCW'({cfg_page, pc_val});
        else if (!src_imem) pc_n = pc;
`ifdef FUZZ_PLANT_RTL2
        // PLANT 2: docs/mvp-isa.md `pc_update`, step 3: at WRAP_TOP the next PC is
        // WRAP_BOTTOM.
        else if (WCW'(pc) == (WCW'({cfg_page, 5'd0}) | WCW'(cfg_wrap_top))) pc_n = pc + PCW'(1);
`else
        else if (WCW'(pc) == (WCW'({cfg_page, 5'd0}) | WCW'(cfg_wrap_top))) pc_n = PCW'({cfg_page, cfg_wrap_bottom});
`endif
        else pc_n = pc + PCW'(1);
        if (!is_exec && !(!src_imem && latch_host)) delay_n = delay_val;
      end
    end

    // background_autopull(): every SM cycle that does not execute an OUT
    if (sm_cycle && !(exec_i && is_out)) begin
      if (cfg_autopull && osr_cnt_n >= pull_th && !tx_empty && !tx_pop) begin
        tx_pop    = 1'b1;
        osr_n     = tx_head;
        osr_cnt_n = 6'd0;
      end
    end

    // OUT/SET window
    os_m32 = rotl(lowmask(os_count), os_base);
    os_d32 = rotl(os_val, os_base) & os_m32;

    // CTRL.SM_RESTART (### Enable, restart): wins over the engine for these fields
    if (sm_restart) begin
      isr_n        = 32'd0;
      osr_cnt_n    = 6'd32;
      isr_cnt_n    = 6'd0;
      delay_n      = 5'd0;
      stalled_n    = 1'b0;
      latch_pend_n = 1'b0;
      latch_host_n = 1'b0;
      forced_n     = 1'b0;
    end

    // host SMe_INSTR write (### EXEC): the host wins the latch
    if (reg_we[4]) begin
      latch_n      = wdata[15:0];
      latch_host_n = 1'b1;
      forced_n     = 1'b1;
    end
  end

  assign os_mask = os_m32[17:0];
  assign os_data = os_d32[17:0];
  assign ss_mask = ss_m32[17:0];
  assign ss_data = ss_d32[17:0];

  // Pin-space bits above 17 do not exist (docs/mvp-isa.md "## Pins").
  logic unused_pins;
  assign unused_pins = ^{os_m32[31:18], os_d32[31:18], ss_m32[31:18], ss_d32[31:18]};

  // SMe_ADDR is read-only
  logic unused_we;
  assign unused_we = reg_we[3];

  // ---------------------------------------------------------------------------------------
  // State registers
  // ---------------------------------------------------------------------------------------

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pc         <= '0;
      x          <= '0;
      y          <= '0;
      osr        <= '0;
      isr        <= '0;
      osr_cnt    <= 6'd32;
      isr_cnt    <= '0;
      delay_cnt  <= '0;
      stalled    <= 1'b0;
      latch      <= '0;
      latch_pend <= 1'b0;
      latch_host <= 1'b0;
      forced     <= 1'b0;
    end else begin
      pc         <= pc_n;
      x          <= x_n;
      y          <= y_n;
      osr        <= osr_n;
      isr        <= isr_n;
      osr_cnt    <= osr_cnt_n;
      isr_cnt    <= isr_cnt_n;
      delay_cnt  <= delay_n;
      stalled    <= stalled_n;
      latch      <= latch_n;
      latch_pend <= latch_pend_n;
      latch_host <= latch_host_n;
      forced     <= forced_n;
    end
  end

  // ---------------------------------------------------------------------------------------
  // The fetch register and the IMEM behind it: IR <= IMEM[PC_next], IMEM as it stands this
  // cycle. `pc_n` is combinational, so the address is on the IMEM read port before the edge
  // and `ir` holds the word that address holds at the edge -- which is what the flop line
  // this replaces did. Both implementations below drive the same `ir` and are written by the
  // same host write port, so the only difference is where the 32 words are stored
  // (research/imem-sram/RESULT.md "## Cycle-exactness").
  // ---------------------------------------------------------------------------------------
  generate
    if (IMEM_SRAM) begin : g_imem_sram
      if (IMEM_WORDS != 32) begin : g_bad
        $error("IMEM_SRAM supports 32 words per engine only");
      end
      pio_imem_sram #(
          .AW       (5),
          .INIT_ZERO(IMEM_INIT_ZERO)
      ) u_imem (
          .clk     (clk),
          .rst_n   (rst_n),
          .rd_addr (pc_n),
          .wr_en   (imem_we),
          .wr_addr (imem_addr),
          .wr_data (wdata[15:0]),
          .ir      (ir)
      );
    end else begin : g_imem_flop
      logic [15:0] imem[IMEM_WORDS];

      always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) ir <= '0;
        else ir <= imem[pc_n];
      end

      // IMEM: 32 x 16 flops, host write port only (INSTR_MEMk, write-only)
      always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
          for (int i = 0; i < IMEM_WORDS; i++) imem[i] <= '0;
        end else if (imem_we) begin
          imem[imem_addr] <= wdata[15:0];
        end
      end
    end
  endgenerate

  // ---------------------------------------------------------------------------------------
  // Register read values
  // ---------------------------------------------------------------------------------------

  assign r_clkdiv    = {cfg_int, cfg_frac, 8'd0};
  assign r_execctrl  = {latch_pend & latch_host, cfg_side_en, cfg_side_pindir, cfg_jmp_pin,
                        2'd0, cfg_page, 3'd0, cfg_wrap_top, cfg_wrap_bottom, 2'd0, cfg_status_sel,
                        cfg_status_n};
  assign r_shiftctrl = {2'd0, cfg_pull_thresh, cfg_push_thresh, cfg_out_right, cfg_in_right,
                        cfg_autopull, cfg_autopush, 16'd0};
  assign r_addr      = 32'(pc);
  assign r_instr     = {16'd0, ir};
  assign r_pinctrl   = {cfg_sideset_count, cfg_set_count, cfg_out_count, cfg_in_base,
                        cfg_sideset_base, cfg_set_base, cfg_out_base};
endmodule
